class Agent:
    def __init__(self, backend, registry, startup_timeout_ms, retry_interval_ms):
        self.backend = backend
        self.registry = registry
        self.startup_timeout_ms = int(startup_timeout_ms)
        self.retry_interval_ms = int(retry_interval_ms)
        self.status = "ok"
        self.diagnostics = []

    def start(self):
        if self.backend.is_ready():
            self.registry.register(self.backend.fetch_tools())
            self.status = "ok"
            self.diagnostics = []
            return
        if self.backend.startup_delay_ms <= self.startup_timeout_ms:
            self.registry.register(self.backend.fetch_tools())
            self.status = "ok"
            self.diagnostics = ["backend_ready_after_wait"]
            return
        self.registry.register([])
        self.status = "degraded"
        self.diagnostics = ["backend_not_ready", "startup_timeout"]

    def call_tools(self, tool_calls):
        results = []
        for name in tool_calls:
            if self.registry.has(name):
                results.append({"tool": name, "result": "ok"})
            else:
                results.append({"tool": name, "result": "unknown_tool"})
        return results

